local k={4,80,118,248,42,229,14,122,99,63,6,182,247,223,137,247,48,253,118,230,168,126,213,38,121,206,141,58,70,53,171,2}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
